export function LoadingState({
  contentLabel = "{{contentLabel}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  showSpinner = {{showSpinner}},
}) {
  return (
    <div role="status" aria-label={`${contentLabel} is ${stage}`} style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      {stage === "idle" && <p style={{ margin: 0, color: "#24143080" }}>Not requested yet</p>}
      {stage === "loading" && (
        <p style={{ margin: 0, display: "flex", alignItems: "center", gap: 8, fontWeight: 600 }}>
          {showSpinner && <span style={{ width: 14, height: 14, borderRadius: "50%", border: "2px solid #24143020", borderTopColor: accent, display: "inline-block" }} />}
          Loading {contentLabel}&hellip;
        </p>
      )}
      {stage === "loaded" && <p style={{ margin: 0, fontWeight: 600, color: accent }}>{contentLabel} loaded</p>}
      {stage === "error" && <p style={{ margin: 0, fontWeight: 600, color: "#E8A020" }}>Failed to load {contentLabel}</p>}
    </div>
  );
}
